    rotate([x,y,z,t]){const d=-s*x+c*z;return [c*x+s*z,p*y-q*d,q*y+p*d,t]},
    project([x,y,z]){return [cols/2+xScale*x,rows/2-scale*(y+.34),z]},
    delta(x,y){return [c*x+s*q*y,p*y,s*x-c*q*y]},
